const hostLifecycleCode = `var host = YggdrasilHost.CreateBuilder("config/app.yaml")
    .BeforeConfigurationLoad(builder => { /* add a trusted config source */ })
    .AfterConfigurationLoad((builder, configuration) => { /* inspect merged config */ })
    .BeforeServiceRegistration(services => { /* register overrides */ })
    .AfterServiceRegistration(services => { /* register application services */ })
    .ConfigureMiddleware(app => { /* enrich identity before authorization */ })
    .AfterHostBuild(builtHost => { /* final host-only adjustment */ })
    .UseBuiltInPlugin<MyPlugin>()
    .Build();

await host.RunAsync();`;

const middlewarePipeline = `UseAsgardStaticFiles
UseAsgardRequestTracing
UseRouting
UseCors                         # when host.cors.enabled
UseRateLimiter                  # when host.rateLimiting.enabled
UseAuthentication              # when host.auth.enabled
UseAsgardTenant
Host ConfigureMiddleware hook
Plugin ConfigureMiddlewareAsync hooks
UseAuthorization               # always
UseSwagger / UseSwaggerUI      # when enabled
MapHealthChecks
MapTsGenerationEndpoint        # Development + enabled
MapControllers`;

const healthRateYaml = `host:
  rateLimiting:
    enabled: true
    policy: SlidingWindow       # FixedWindow | SlidingWindow | TokenBucket
    permitLimit: 100
    windowSeconds: 60
    segmentsPerWindow: 10
    queueLimit: 0

  healthCheck:
    enabled: true
    path: /health
    readyPath: /health/ready
    livePath: /health/live
    timeoutSeconds: 30`;

const tokenBucketYaml = `host:
  rateLimiting:
    enabled: true
    policy: TokenBucket
    permitLimit: 1          # still validated in 5.1.3
    windowSeconds: 1       # still validated in 5.1.3
    segmentsPerWindow: 1   # still validated in 5.1.3
    tokenLimit: 200
    tokensPerSecond: 20
    queueLimit: 0`;

const readinessRegistrationCode = `var builder = YggdrasilHost.CreateBuilder("config/app.yaml")
    .AfterServiceRegistration(services =>
    {
        _ = services.AddHealthChecks()
            .AddCheck<PostgresReadinessCheck>("postgres", tags: ["ready"])
            .AddCheck<RedisReadinessCheck>("redis", tags: ["ready"]);
    });

var app = builder.Build();
await app.RunAsync();`;

const healthRateAcceptance = `# Health semantics: dependency failure must affect ready, not live.
curl --fail http://127.0.0.1:8080/health/live
curl --fail http://127.0.0.1:8080/health/ready

# Capture status, headers, and body around the configured threshold.
curl --include http://127.0.0.1:8080/api/ping

# Repeat from each replica/network path. Static assets are a separate bypass path.
curl --include http://127.0.0.1:8080/assets/app.js`;

const pluginLifecycleCode = `public sealed class OrdersPlugin : PluginBase
{
    public override string Id => "orders";
    public override string Name => "Orders";
    public override Version Version => new(1, 0, 0);

    protected override Task OnConfigureServicesAsync(
        IPluginServiceConfigurationContext context,
        CancellationToken cancellationToken)
    {
        _ = context.Services.AddScoped<IOrderService, OrderService>();
        return Task.CompletedTask;
    }

    protected override Task OnInitializeAsync(CancellationToken cancellationToken)
    {
        var logger = CreateLogger();
        logger.LogInformation("订单插件初始化完成");
        return Task.CompletedTask;
    }

    protected override Task OnConfigureMiddlewareAsync(
        IPluginMiddlewareConfigurationContext context,
        CancellationToken cancellationToken)
    {
        if (context.App is IEndpointRouteBuilder endpoints)
        {
            _ = endpoints.MapFallback("/orders/{**path}", static () => Results.NotFound());
        }

        return Task.CompletedTask;
    }
}`;

