    slug: "host-lifecycle", group: "Host Runtime", eyebrow: "BUILD PHASES", title: "Host build lifecycle", description: "Put configuration, infrastructure, services, plugins, and the Web pipeline into the correct Yggdrasil build phase.", sections: [
      { id: "phases", title: "The five build phases", bullets: ["Phase 1 merges app.yaml, environment YAML, environment variables, and command-line configuration", "Phase 2 loads and validates Host, Logging, Trace, Cache, Database, MQ, Job, and Plugin configuration", "Phase 3 synchronously initializes enabled Trace, Cache, MQ, and Job managers", "Phase 4 registers framework, database, security, MVC, plugins, health checks, rate limiting, and hosted services", "Phase 5 builds the container, initializes and starts plugins, then configures middleware"] },
      { id: "hooks", title: "What belongs in each hook", paragraphs: ["BeforeConfigurationLoad can observe or add ASP.NET configuration sources and AfterConfigurationLoad inspects the merged view. Asgard typed module objects come from the framework's own configuration graph; do not assume a hook-added provider overrides them. Framework registrations can replace a BeforeServiceRegistration entry. AfterServiceRegistration is better for application services, although Swagger is still added afterwards. ConfigureMiddleware is fixed after tenant context and before authorization. AfterHostBuild runs after plugins and pipeline assembly but before listening starts.", "Each hook stores one delegate. Calling the same hook twice replaces the earlier delegate instead of composing it; place multiple ordered actions in one callback."], code: { language: "csharp", value: hostLifecycleCode } },
      { id: "build", title: "Build does more than create the container", paragraphs: ["CreateBuilder construction already reads the base app.yaml, validates HostConfig/LogConfig, and creates bootstrap logging. The base file must therefore be valid without later environment overrides. Build() then initializes infrastructure and initializes/starts plugins synchronously before RunAsync. Configuration, service-registration, or dependency-graph failures can stop the build. Do not put unbounded network work into build hooks."] },
      { id: "availability", title: "Capability availability", bullets: ["Service registration has IServiceCollection but not the final provider", "Plugin GetService, CreateLogger, and GetAsgardContext become valid in InitializeAsync", "JobManager receives the final provider after WebApplication is built", "Plugin middleware is attached after plugin Initialize/Start succeeds"] },
      { id: "shutdown", title: "Shutdown boundary", paragraphs: ["On host stop, AsgardRuntimeHostedService shuts down the active job scheduler before disposing PluginManager. Plugins must still make Stop/Dispose idempotent and ensure their own background work observes CancellationToken."] },
    ],
